    with app.step('Click Delete this chat button once', action='click', element='home.delete_this_chat_button'):
        app.click(app.pages.home.delete_this_chat_button)
    with app.step('Verify conversation heading remains (chat not immediately deleted)', action='expect_visible', element='home.good_afternoon_karthik_heading'):
        expect(app.pages.home.good_afternoon_karthik_heading).to_be_visible()
